from AlgorithmImports import *
from System import Decimal


class IndependentDailySlotsAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self._spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self._aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self._ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self._bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self._aig = self.AddEquity("AIG", Resolution.Daily).Symbol
        self._symbols = (self._spy, self._aapl, self._ibm, self._bac, self._aig)

        self._spy_sma = SimpleMovingAverage("SPY_SMA_100", 100)
        self._aapl_rsi = RelativeStrengthIndex(
            "AAPL_RSI_14", 14, MovingAverageType.Wilders
        )

        self._strategy_a_lot = 0
        self._strategy_b_lot = 0

        self._spy_previous_close = None
        self._spy_previous_sma = None
        self._spy_current_close = None
        self._spy_current_sma = None

        self._aapl_previous_close = None
        self._aapl_current_close = None
        self._aapl_red_streak = 0
        self._aapl_close_count = 0

        self._forty_percent = Decimal(40) / Decimal(100)
        self._aapl_buy_amount = Decimal(20000)

        self.SetWarmUp(100, Resolution.Daily)

    def OnData(self, data):
        has_spy = data.Bars.ContainsKey(self._spy)
        has_aapl = data.Bars.ContainsKey(self._aapl)

        if has_spy:
            self._update_spy_state(data.Bars[self._spy])

        if has_aapl:
            self._update_aapl_state(data.Bars[self._aapl])

        self._refresh_lots()

        if self.IsWarmingUp:
            return

        if not all(data.Bars.ContainsKey(symbol) for symbol in self._symbols):
            return

        if not self._rule_inputs_ready():
            return

        if self._strategy_a_lot > 0 and self._spy_crossed_below_sma():
            self.MarketOrder(self._spy, -self._strategy_a_lot)
            self._refresh_lots()

        if self._strategy_b_lot > 0 and self._aapl_rsi.Current.Value > 60:
            self.MarketOrder(self._aapl, -self._strategy_b_lot)
            self._refresh_lots()

        if self._strategy_a_lot == 0 and self._spy_crossed_above_sma():
            target_value = self.Portfolio.TotalPortfolioValue * self._forty_percent
            quantity = int(target_value / self._spy_current_close)

            if quantity > 0:
                self.MarketOrder(self._spy, quantity)
                self._refresh_lots()

        if self._strategy_b_lot == 0 and self._aapl_red_streak >= 3:
            if self.Portfolio.Cash >= self._aapl_buy_amount:
                quantity = int(self._aapl_buy_amount / self._aapl_current_close)

                if quantity > 0:
                    self.MarketOrder(self._aapl, quantity)
                    self._refresh_lots()

    def _update_spy_state(self, bar):
        self._spy_sma.Update(IndicatorDataPoint(bar.EndTime, bar.Close))

        if not self._spy_sma.IsReady:
            return

        self._spy_previous_close = self._spy_current_close
        self._spy_previous_sma = self._spy_current_sma
        self._spy_current_close = bar.Close
        self._spy_current_sma = self._spy_sma.Current.Value

    def _update_aapl_state(self, bar):
        self._aapl_rsi.Update(IndicatorDataPoint(bar.EndTime, bar.Close))

        if self._aapl_previous_close is not None:
            if bar.Close < self._aapl_previous_close:
                self._aapl_red_streak += 1
            else:
                self._aapl_red_streak = 0

        self._aapl_previous_close = bar.Close
        self._aapl_current_close = bar.Close
        self._aapl_close_count += 1

    def _refresh_lots(self):
        self._strategy_a_lot = max(0, int(self.Portfolio[self._spy].Quantity))
        self._strategy_b_lot = max(0, int(self.Portfolio[self._aapl].Quantity))

    def _rule_inputs_ready(self):
        return (
            self._spy_sma.IsReady
            and self._aapl_rsi.IsReady
            and self._spy_previous_close is not None
            and self._spy_previous_sma is not None
            and self._spy_current_close is not None
            and self._spy_current_sma is not None
            and self._aapl_current_close is not None
            and self._aapl_close_count >= 4
        )

    def _spy_crossed_above_sma(self):
        return (
            self._spy_previous_close <= self._spy_previous_sma
            and self._spy_current_close > self._spy_current_sma
        )

    def _spy_crossed_below_sma(self):
        return (
            self._spy_previous_close >= self._spy_previous_sma
            and self._spy_current_close < self._spy_current_sma
        )

