from AlgorithmImports import *


class TwoSlotPrivateLotAlgorithm(QCAlgorithm):
    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self._spy = self.add_equity("SPY", Resolution.DAILY, fill_forward=False).symbol
        self._aapl = self.add_equity("AAPL", Resolution.DAILY, fill_forward=False).symbol
        self._ibm = self.add_equity("IBM", Resolution.DAILY, fill_forward=False).symbol
        self._bac = self.add_equity("BAC", Resolution.DAILY, fill_forward=False).symbol
        self._aig = self.add_equity("AIG", Resolution.DAILY, fill_forward=False).symbol

        self._symbols = [self._spy, self._aapl, self._ibm, self._bac, self._aig]

        self._spy_sma = SimpleMovingAverage(100)
        self._aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.WILDERS)

        self._last_spy_close = None
        self._previous_spy_close = None
        self._previous_spy_sma = None

        self._last_aapl_close = None
        self._aapl_red_streak = 0

        self._strategy_a_lot = 0
        self._strategy_b_lot = 0

    def on_data(self, data: Slice):
        bars = data.bars

        if bars.contains_key(self._spy):
            self._update_spy_state(bars[self._spy])

        if bars.contains_key(self._aapl):
            self._update_aapl_state(bars[self._aapl])

        if not all(bars.contains_key(symbol) for symbol in self._symbols):
            return

        if not self._rules_ready():
            return

        spy_close = bars[self._spy].close
        aapl_close = bars[self._aapl].close
        available_cash = float(self.portfolio.cash)

        # Evaluate all sells before any buys.
        if self._strategy_a_lot > 0 and self._spy_crosses_below_sma(spy_close):
            shares = self._strategy_a_lot
            self.market_order(self._spy, -shares)
            self._strategy_a_lot = 0
            available_cash += shares * float(spy_close)

        if self._strategy_b_lot > 0 and self._aapl_rsi.current.value > 60:
            shares = self._strategy_b_lot
            self.market_order(self._aapl, -shares)
            self._strategy_b_lot = 0
            available_cash += shares * float(aapl_close)

        if self._strategy_a_lot == 0 and self._spy_crosses_above_sma(spy_close):
            quantity = int(
                0.40 * float(self.portfolio.total_portfolio_value) / float(spy_close)
            )
            if quantity > 0:
                self.market_order(self._spy, quantity)
                self._strategy_a_lot = quantity
                available_cash -= quantity * float(spy_close)

        if (
            self._strategy_b_lot == 0
            and self._aapl_red_streak >= 3
            and available_cash >= 20_000
        ):
            quantity = int(20_000 / float(aapl_close))
            if quantity > 0:
                self.market_order(self._aapl, quantity)
                self._strategy_b_lot = quantity

    def _update_spy_state(self, bar: TradeBar):
        self._previous_spy_close = self._last_spy_close
        self._previous_spy_sma = (
            self._spy_sma.current.value if self._spy_sma.is_ready else None
        )

        self._spy_sma.update(bar.end_time, bar.close)
        self._last_spy_close = bar.close

    def _update_aapl_state(self, bar: TradeBar):
        if self._last_aapl_close is None or bar.close >= self._last_aapl_close:
            self._aapl_red_streak = 0
        else:
            self._aapl_red_streak += 1

        self._aapl_rsi.update(bar.end_time, bar.close)
        self._last_aapl_close = bar.close

    def _rules_ready(self) -> bool:
        return (
            self._spy_sma.is_ready
            and self._aapl_rsi.is_ready
            and self._previous_spy_close is not None
            and self._previous_spy_sma is not None
        )

    def _spy_crosses_above_sma(self, current_close) -> bool:
        return (
            self._previous_spy_close <= self._previous_spy_sma
            and current_close > self._spy_sma.current.value
        )

    def _spy_crosses_below_sma(self, current_close) -> bool:
        return (
            self._previous_spy_close >= self._previous_spy_sma
            and current_close < self._spy_sma.current.value
        )

