        self.previous_aapl_close = current_close

    def _adjust_private_lots_for_splits(self, data):
        if data.Splits.ContainsKey(self.spy):
            split = data.Splits[self.spy]
            if split.Type == SplitType.SplitOccurred and self.strategy_a_lot_shares > 0:
                self.strategy_a_lot_shares = int(
