class IndependentParallelSlotsAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self._symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self._symbols[ticker] = self.AddEquity(
                ticker, Resolution.Daily, Market.USA, False
            ).Symbol

        self._spy = self._symbols["SPY"]
        self._aapl = self._symbols["AAPL"]

        self._spy_sma = self.SMA(self._spy, 100, Resolution.Daily)
        self._aapl_rsi = self.RSI(
            self._aapl, 14, MovingAverageType.Wilders, Resolution.Daily
        )

        self._previous_spy_close = None
        self._previous_aapl_close = None
        self._aapl_red_streak = 0

        self._strategy_a_lot_shares = 0
        self._strategy_b_lot_shares = 0
        self._strategy_a_pending = False
        self._strategy_b_pending = False

        self.SetWarmUp(101, Resolution.Daily)

    def OnData(self, data):
        bars = data.Bars
        spy_bar = self._bar_or_none(bars, self._spy)
        aapl_bar = self._bar_or_none(bars, self._aapl)

        previous_spy_close = self._previous_spy_close

        if spy_bar is not None:
            self._previous_spy_close = spy_bar.Close

        if aapl_bar is not None:
            if (
                self._previous_aapl_close is not None
                and aapl_bar.Close < self._previous_aapl_close
            ):
                self._aapl_red_streak += 1
            else:
                self._aapl_red_streak = 0

            self._previous_aapl_close = aapl_bar.Close

        if self.IsWarmingUp:
            return

        if any(
            self._bar_or_none(bars, symbol) is None
            for symbol in self._symbols.values()
        ):
            return

        if (
            not self._spy_sma.IsReady
            or self._spy_sma.Samples < 101
            or not self._aapl_rsi.IsReady
            or previous_spy_close is None
        ):
            return

        spy_crosses_above_sma = (
            previous_spy_close <= self._spy_sma.Previous.Value
            and spy_bar.Close > self._spy_sma.Current.Value
        )
        spy_crosses_below_sma = (
            previous_spy_close >= self._spy_sma.Previous.Value
            and spy_bar.Close < self._spy_sma.Current.Value
        )

        # Evaluate sells before buys.
        if (
            self._strategy_a_lot_shares > 0
            and not self._strategy_a_pending
            and spy_crosses_below_sma
        ):
            self._submit_strategy_a_order(-self._strategy_a_lot_shares)

        if (
            self._strategy_b_lot_shares > 0
            and not self._strategy_b_pending
            and self._aapl_rsi.Current.Value > 60
        ):
            self._submit_strategy_b_order(-self._strategy_b_lot_shares)

        if (
            self._strategy_a_lot_shares == 0
            and not self._strategy_a_pending
            and spy_crosses_above_sma
        ):
            quantity = int(
                (self.Portfolio.TotalPortfolioValue * 40)
                / (spy_bar.Close * 100)
            )
            if quantity > 0:
                self._submit_strategy_a_order(quantity)

        if (
            self._strategy_b_lot_shares == 0
            and not self._strategy_b_pending
            and self._aapl_red_streak >= 3
        ):
            available_cash = self.Portfolio.CashBook["USD"].Amount
            if available_cash >= 20_000:
                quantity = int(20_000 / aapl_bar.Close)
                if quantity > 0:
                    self._submit_strategy_b_order(quantity)

    def OnOrderEvent(self, order_event):
        if order_event.Symbol == self._spy:
            if order_event.FillQuantity != 0:
                self._strategy_a_lot_shares += int(order_event.FillQuantity)

            if order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid,
            ):
                self._strategy_a_pending = False

        elif order_event.Symbol == self._aapl:
            if order_event.FillQuantity != 0:
                self._strategy_b_lot_shares += int(order_event.FillQuantity)

            if order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid,
            ):
                self._strategy_b_pending = False

    def _submit_strategy_a_order(self, quantity):
        self._strategy_a_pending = True
        ticket = self.MarketOrder(self._spy, quantity)
        if ticket.Status in (OrderStatus.Invalid, OrderStatus.Canceled):
            self._strategy_a_pending = False

    def _submit_strategy_b_order(self, quantity):
        self._strategy_b_pending = True
        ticket = self.MarketOrder(self._aapl, quantity)
        if ticket.Status in (OrderStatus.Invalid, OrderStatus.Canceled):
            self._strategy_b_pending = False

    def _bar_or_none(self, bars, symbol):
        if bars is None or not bars.ContainsKey(symbol):
            return None
        return bars[symbol]
