from collections import deque
from decimal import Decimal


class ExactDailyTwoSlotAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self._symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self._symbols[ticker] = self.AddEquity(
                ticker, Resolution.Daily, Market.USA, False
            ).Symbol

        self._all_symbols = tuple(self._symbols.values())
        self._spy = self._symbols["SPY"]
        self._aapl = self._symbols["AAPL"]

        self._spy_closes = deque(maxlen=100)
        self._spy_close = None
        self._spy_previous_close = None
        self._spy_sma = None
        self._spy_previous_sma = None

        self._aapl_previous_close = None
        self._aapl_close_count = 0
        self._aapl_red_streak = 0
        self._aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self._strategy_a_lot = 0
        self._strategy_b_lot = 0

        self.SetWarmUp(101, Resolution.Daily)

    def OnData(self, data):
        self._sync_private_lots()

        bars = {}
        for symbol in self._all_symbols:
            if data.Bars.ContainsKey(symbol):
                bars[symbol] = data.Bars[symbol]

        self._update_market_state(bars)

        if self.IsWarmingUp:
            return

        if len(bars) != len(self._all_symbols):
            return

        if not self._all_rule_inputs_ready():
            return

        self._evaluate_slots(bars)

    def _update_market_state(self, bars):
        spy_bar = bars.get(self._spy)
        if spy_bar is not None:
            close = Decimal(str(spy_bar.Close))

            self._spy_previous_close = self._spy_close
            self._spy_previous_sma = self._spy_sma

            self._spy_closes.append(close)
            self._spy_close = close

            if len(self._spy_closes) == 100:
                self._spy_sma = (
                    sum(self._spy_closes, Decimal("0")) / Decimal("100")
                )
            else:
                self._spy_sma = None

        aapl_bar = bars.get(self._aapl)
        if aapl_bar is not None:
            close = Decimal(str(aapl_bar.Close))

            if self._aapl_previous_close is None:
                self._aapl_red_streak = 0
            elif close < self._aapl_previous_close:
                self._aapl_red_streak += 1
            else:
                self._aapl_red_streak = 0

            self._aapl_previous_close = close
            self._aapl_close_count += 1
            self._aapl_rsi.Update(aapl_bar.EndTime, aapl_bar.Close)

    def _all_rule_inputs_ready(self):
        return (
            len(self._spy_closes) == 100
            and self._spy_close is not None
            and self._spy_previous_close is not None
            and self._spy_sma is not None
            and self._spy_previous_sma is not None
            and self._aapl_close_count >= 4
            and self._aapl_rsi.IsReady
        )

    def _spy_crossed_above_sma(self):
        return (
            self._spy_previous_close <= self._spy_previous_sma
            and self._spy_close > self._spy_sma
        )

    def _spy_crossed_below_sma(self):
        return (
            self._spy_previous_close >= self._spy_previous_sma
            and self._spy_close < self._spy_sma
        )

    def _has_open_orders(self, symbol):
        return bool(list(self.Transactions.GetOpenOrders(symbol)))

    def _sync_private_lots(self):
        if not self._has_open_orders(self._spy):
            self._strategy_a_lot = max(
                0, int(self.Portfolio[self._spy].Quantity)
            )

        if not self._has_open_orders(self._aapl):
            self._strategy_b_lot = max(
                0, int(self.Portfolio[self._aapl].Quantity)
            )

    def _evaluate_slots(self, bars):
        a_lot = self._strategy_a_lot
        b_lot = self._strategy_b_lot

        # Sell phase
        if a_lot > 0 and self._spy_crossed_below_sma():
            self.MarketOrder(self._spy, -a_lot)
            a_lot = 0

        if (
            b_lot > 0
            and Decimal(str(self._aapl_rsi.Current.Value)) > Decimal("60")
        ):
            self.MarketOrder(self._aapl, -b_lot)
            b_lot = 0

        portfolio_value = Decimal(str(self.Portfolio.TotalPortfolioValue))
        available_cash = Decimal(str(self.Portfolio.Cash))

        # Buy phase
        if a_lot == 0 and self._spy_crossed_above_sma():
            spy_close = Decimal(str(bars[self._spy].Close))
            if spy_close > 0:
                quantity = int(
                    (portfolio_value * Decimal("0.40")) / spy_close
                )
                if quantity > 0:
                    self.MarketOrder(self._spy, quantity)
                    a_lot = quantity

        if b_lot == 0 and self._aapl_red_streak >= 3:
            purchase_amount = Decimal("20000")
            if available_cash >= purchase_amount:
                aapl_close = Decimal(str(bars[self._aapl].Close))
                if aapl_close > 0:
                    quantity = int(purchase_amount / aapl_close)
                    if quantity > 0:
                        self.MarketOrder(self._aapl, quantity)
                        b_lot = quantity

        self._strategy_a_lot = a_lot
        self._strategy_b_lot = b_lot

