        self._all_symbols = [self._spy, self._aapl, self._ibm, self._bac, self._aig]

        self._spy_sma = SimpleMovingAverage(100)
        self._aapl_rsi = RelativeStrengthIndex(14)

        self._spy_closes = deque(maxlen=2)
        self._spy_ma_values = deque(maxlen=2)
        self._aapl_closes = deque(maxlen=4)

        self._a_lot_shares = 0
        self._b_lot_shares = 0
        self._a_ticket = None
        self._b_ticket = None

    def OnData(self, data):
        bars = data.Bars

        if bars.ContainsKey(self._spy):
            spy_bar = bars[self._spy]
            self._spy_sma.Update(self.Time, spy_bar.Close)
            self._spy_closes.append(self._to_decimal(spy_bar.Close))

            if self._spy_sma.IsReady:
                self._spy_ma_values.append(
                    self._to_decimal(self._spy_sma.Current.Value)
                )

        if bars.ContainsKey(self._aapl):
            aapl_bar = bars[self._aapl]
            self._aapl_rsi.Update(self.Time, aapl_bar.Close)
            self._aapl_closes.append(self._to_decimal(aapl_bar.Close))

        self._refresh_lots()
        self._clear_finished_tickets()

        if self.IsWarmingUp:
            return

        if not all(bars.ContainsKey(symbol) for symbol in self._all_symbols):
            return

        if not self._history_ready():
            return

        # Sells are evaluated before buys.
        if (
            self._a_lot_shares > 0
            and not self._ticket_is_open(self._a_ticket)
            and self._spy_crossed_below_ma()
        ):
            self._sell_strategy_a()

        if (
            self._b_lot_shares > 0
            and not self._ticket_is_open(self._b_ticket)
            and self._aapl_rsi_above_60()
        ):
            self._sell_strategy_b()

        if (
            self._a_lot_shares == 0
            and not self._ticket_is_open(self._a_ticket)
            and self._spy_crossed_above_ma()
        ):
            self._buy_strategy_a(self._spy_closes[-1])

        if (
            self._b_lot_shares == 0
            and not self._ticket_is_open(self._b_ticket)
            and self._aapl_red_for_three_days()
        ):
            self._buy_strategy_b(self._aapl_closes[-1])

    def _history_ready(self):
        return (
            self._spy_sma.IsReady
            and self._aapl_rsi.IsReady
            and len(self._spy_closes) == 2
            and len(self._spy_ma_values) == 2
            and len(self._aapl_closes) == 4
        )

    def _spy_crossed_above_ma(self):
        return (
            self._spy_closes[-2] <= self._spy_ma_values[-2]
            and self._spy_closes[-1] > self._spy_ma_values[-1]
        )

    def _spy_crossed_below_ma(self):
        return (
            self._spy_closes[-2] >= self._spy_ma_values[-2]
            and self._spy_closes[-1] < self._spy_ma_values[-1]
        )

    def _aapl_red_for_three_days(self):
        return (
            self._aapl_closes[-1] < self._aapl_closes[-2]
            and self._aapl_closes[-2] < self._aapl_closes[-3]
            and self._aapl_closes[-3] < self._aapl_closes[-4]
        )

    def _aapl_rsi_above_60(self):
        return self._to_decimal(self._aapl_rsi.Current.Value) > Decimal("60")

    def _buy_strategy_a(self, close):
        target_value = self._to_decimal(self.Portfolio.TotalPortfolioValue) * Decimal("0.40")
        quantity = int(target_value / close)

        if quantity > 0:
            self._a_ticket = self.MarketOrder(
                self._spy, quantity, False, "Strategy A buy"
            )
            self._refresh_lots()

    def _sell_strategy_a(self):
        self._a_ticket = self.MarketOrder(
            self._spy, -self._a_lot_shares, False, "Strategy A sell"
        )
        self._refresh_lots()

    def _buy_strategy_b(self, close):
        required_cash = Decimal("20000")

        if self._to_decimal(self.Portfolio.Cash) < required_cash:
            return

        quantity = int(required_cash / close)

        if quantity > 0:
            self._b_ticket = self.MarketOrder(
                self._aapl, quantity, False, "Strategy B buy"
            )
            self._refresh_lots()

    def _sell_strategy_b(self):
        self._b_ticket = self.MarketOrder(
            self._aapl, -self._b_lot_shares, False, "Strategy B sell"
        )
        self._refresh_lots()

    def _refresh_lots(self):
        self._a_lot_shares = max(0, int(self.Portfolio[self._spy].Quantity))
        self._b_lot_shares = max(0, int(self.Portfolio[self._aapl].Quantity))

    def _clear_finished_tickets(self):
        if not self._ticket_is_open(self._a_ticket):
            self._a_ticket = None

        if not self._ticket_is_open(self._b_ticket):
            self._b_ticket = None

    @staticmethod
    def _ticket_is_open(ticket):
        return ticket is not None and ticket.Status not in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid,
        )

    @staticmethod
    def _to_decimal(value):
        return Decimal(str(value))
