from AlgorithmImports import *


class ExactDailyTwoSlotStrategy(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)
        self.SetWarmUp(100, Resolution.Daily)

        self._symbols = []
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            security = self.AddEquity(ticker, Resolution.Daily, Market.USA, False)
            self._symbols.append(security.Symbol)

        self._spy = self.Symbol("SPY")
        self._aapl = self.Symbol("AAPL")

        self._spy_sma = SimpleMovingAverage(100)
        self._aapl_rsi = RelativeStrengthIndex(14)

        self._strategy_a_lot = 0
        self._strategy_b_lot = 0

        self._last_spy_bar_end_time = None
        self._last_aapl_bar_end_time = None
        self._last_evaluation_time = None

        self._spy_last_close = None
        self._spy_last_sma = None
        self._spy_previous_close = None
        self._spy_previous_sma = None
        self._spy_previous_sma_ready = False
        self._spy_current_close = None
        self._spy_current_sma = None

        self._aapl_last_close = None
        self._aapl_red_streak = 0
        self._aapl_close_count = 0

    def OnData(self, data):
        self._update_market_state(data)
        self._sync_lot_quantities()

        if not self._all_bars_present(data):
            return

        evaluation_time = data.Bars[self._spy].EndTime
        if self._last_evaluation_time == evaluation_time:
            return
        self._last_evaluation_time = evaluation_time

        if self.IsWarmingUp or not self._rules_ready():
            return

        # Sells are evaluated before buys.
        if self._strategy_a_lot > 0 and self._spy_crossed_below_sma():
            self._sell_strategy_a()

        if self._strategy_b_lot > 0 and self._aapl_rsi.Current.Value > 60:
            self._sell_strategy_b()

        if self._strategy_a_lot == 0 and self._spy_crossed_above_sma():
            self._buy_strategy_a(self._spy_current_close)

        if self._strategy_b_lot == 0 and self._aapl_red_streak >= 3:
            self._buy_strategy_b(data.Bars[self._aapl].Close)

    def _all_bars_present(self, data):
        for symbol in self._symbols:
            if not data.Bars.ContainsKey(symbol) or data.Bars[symbol] is None:
                return False
        return True

    def _update_market_state(self, data):
        if data.Bars.ContainsKey(self._spy) and data.Bars[self._spy] is not None:
            self._update_spy_state(data.Bars[self._spy])

        if data.Bars.ContainsKey(self._aapl) and data.Bars[self._aapl] is not None:
            self._update_aapl_state(data.Bars[self._aapl])

    def _update_spy_state(self, bar):
        if (
            self._last_spy_bar_end_time is not None
            and bar.EndTime <= self._last_spy_bar_end_time
        ):
            return

        self._spy_previous_close = self._spy_last_close
        self._spy_previous_sma = self._spy_last_sma
        self._spy_previous_sma_ready = self._spy_sma.IsReady

        self._spy_sma.Update(bar.EndTime, bar.Close)

        self._spy_current_close = bar.Close
        self._spy_current_sma = self._spy_sma.Current.Value
        self._spy_last_close = bar.Close
        self._spy_last_sma = self._spy_sma.Current.Value
        self._last_spy_bar_end_time = bar.EndTime

    def _update_aapl_state(self, bar):
        if (
            self._last_aapl_bar_end_time is not None
            and bar.EndTime <= self._last_aapl_bar_end_time
        ):
            return

        if self._aapl_last_close is not None:
            if bar.Close < self._aapl_last_close:
                self._aapl_red_streak += 1
            else:
                self._aapl_red_streak = 0

        self._aapl_rsi.Update(bar.EndTime, bar.Close)
        self._aapl_last_close = bar.Close
        self._aapl_close_count += 1
        self._last_aapl_bar_end_time = bar.EndTime

    def _sync_lot_quantities(self):
        if self._strategy_a_lot > 0:
            self._strategy_a_lot = max(0, int(self.Portfolio[self._spy].Quantity))

        if self._strategy_b_lot > 0:
            self._strategy_b_lot = max(0, int(self.Portfolio[self._aapl].Quantity))

    def _rules_ready(self):
        return (
            self._spy_sma.IsReady
            and self._spy_previous_sma_ready
            and self._spy_previous_close is not None
            and self._spy_previous_sma is not None
            and self._aapl_rsi.IsReady
            and self._aapl_close_count >= 4
        )

    def _spy_crossed_above_sma(self):
        return (
            self._spy_previous_close <= self._spy_previous_sma
            and self._spy_current_close > self._spy_current_sma
        )

    def _spy_crossed_below_sma(self):
        return (
            self._spy_previous_close >= self._spy_previous_sma
            and self._spy_current_close < self._spy_current_sma
        )

    def _buy_strategy_a(self, close):
        quantity = int((self.Portfolio.TotalPortfolioValue * 40 / 100) / close)
        if quantity > 0:
            self.MarketOrder(self._spy, quantity)
            self._strategy_a_lot = quantity

    def _sell_strategy_a(self):
        self.MarketOrder(self._spy, -self._strategy_a_lot)
        self._strategy_a_lot = 0

    def _buy_strategy_b(self, close):
        if self.Portfolio.Cash < 20_000:
            return

        quantity = int(20_000 / close)
        if quantity > 0:
            self.MarketOrder(self._aapl, quantity)
            self._strategy_b_lot = quantity

    def _sell_strategy_b(self):
        self.MarketOrder(self._aapl, -self._strategy_b_lot)
        self._strategy_b_lot = 0

