        ):
            return

        self._spy_previous_close = self._spy_last_close
        self._spy_previous_sma = self._spy_last_sma
        self._spy_previous_sma_ready = self._spy_sma.IsReady

        self._spy_sma.Update(bar.EndTime, bar.Close)

        self._spy_current_close = bar.Close
        self._spy_current_sma = self._spy_sma.Current.Value
        self._spy_last_close = bar.Close
        self._spy_last_sma = self._spy_sma.Current.Value
        self._last_spy_bar_end_time = bar.EndTime

    def _update_aapl_state(self, bar):
        if (
            self._last_aapl_bar_end_time is not None
            and bar.EndTime <= self._last_aapl_bar_end_time
        ):
            return

        if self._aapl_last_close is not None:
            if bar.Close < self._aapl_last_close:
                self._aapl_red_streak += 1
            else:
                self._aapl_red_streak = 0

        self._aapl_rsi.Update(bar.EndTime, bar.Close)
        self._aapl_last_close = bar.Close
        self._aapl_close_count += 1
        self._last_aapl_bar_end_time = bar.EndTime

    def _sync_lot_quantities(self):
        if self._strategy_a_lot > 0:
            self._strategy_a_lot = max(0, int(self.Portfolio[self._spy].Quantity))

        if self._strategy_b_lot > 0:
            self._strategy_b_lot = max(0, int(self.Portfolio[self._aapl].Quantity))

    def _rules_ready(self):
        return (
            self._spy_sma.IsReady
            and self._spy_previous_sma_ready
            and self._spy_previous_close is not None
            and self._spy_previous_sma is not None
            and self._aapl_rsi.IsReady
            and self._aapl_close_count >= 4
        )

    def _spy_crossed_above_sma(self):
        return (
            self._spy_previous_close <= self._spy_previous_sma
            and self._spy_current_close > self._spy_current_sma
        )

    def _spy_crossed_below_sma(self):
        return (
            self._spy_previous_close >= self._spy_previous_sma
            and self._spy_current_close < self._spy_current_sma
        )

    def _buy_strategy_a(self, close):
        quantity = int((self.Portfolio.TotalPortfolioValue * 40 / 100) / close)
        if quantity > 0:
            self.MarketOrder(self._spy, quantity)
            self._strategy_a_lot = quantity

    def _sell_strategy_a(self):
        self.MarketOrder(self._spy, -self._strategy_a_lot)
        self._strategy_a_lot = 0

    def _buy_strategy_b(self, close):
        if self.Portfolio.Cash < 20_000:
            return

        quantity = int(20_000 / close)
        if quantity > 0:
            self.MarketOrder(self._aapl, quantity)
            self._strategy_b_lot = quantity

    def _sell_strategy_b(self):
        self.MarketOrder(self._aapl, -self._strategy_b_lot)
        self._strategy_b_lot = 0
